testcase.failure:
tests/crud_views_tabler/test_theme.py:674: in test_workflow_no_longer_scrolls_the_whole_content_container
    self.assertNotIn(".page-body > .container-xl:has(> table.table)", css)
E   AssertionError: '.page-body > .container-xl:has(> table.table)' unexpectedly found in '/* crispy-forms marks required fields with <span class="asteriskField">*</span>; match Tabler's .form-label.required. */
.asteriskField {
  margin-inline-start: 0.25rem;
  color: var(--tblr-danger);
}

/* Row actions sit at the end of the row and never wrap. */
.card-table td:has(> [cv-list-container]),
.card-table th.cv-actions {
  width: 1%;
  white-space: nowrap;
  text-align: end;
}

/* The filter card and the content below it. */
#filter-collapse > .card,
#filter-pinned {
  margin-bottom: 1rem;
}

/* crud_views wraps the toggle's icons in a span. Tabler's .btn-icon .icon has a negative margin that only works on a
   direct flex child of the button, so the span must generate no box. :not([hidden]) keeps the other icon hidden. */
#cv-filter-toggle [data-cv-filter-icon]:not([hidden]) {
  display: contents;
}

/* crud_views' modal header: the header icon sits beside the title text. */
#cv-modal .modal-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* crud_views' actions menu items: the icon slot (icon or empty placeholder) sized and muted like Tabler's
   .dropdown-item-icon, so labels line up; .dropdown-item supplies the gap. */
.dropdown-item > .cv-icon-fw {
  width: var(--tblr-dropdown-item-icon-size);
  height: var(--tblr-dropdown-item-icon-size);
  color: var(--tblr-dropdown-item-icon-color);
}

/* crud_views' ToggleGroup(legend=...) and the formset title (crud_views/formsets/formset.html) render a bare
   <fieldset><legend>; browsers and Bootstrap size the legend like a heading. Make it a section label like Tabler's
   .card-title. */
.cv-toggle-group > legend,
.cv-formset-fieldset > legend {
  float: none;
  width: auto;
  margin-bottom: 0.75rem;
  font-size: 1rem;
  font-weight: var(--tblr-font-weight-bold, 600);
}

/* django-crud-views-extensions' typeahead skins read Bootstrap's custom properties (--bs-body-bg, ...). Tabler names
   them --tblr-*, so the select popup had no background or border and the form buttons showed through it. Feed the
   components Tabler's values; plain CSS, the theme does not depend on the extensions package. */
.cv-typeahead,
.cv-typeahead-select {
  --bs-body-bg: var(--tblr-bg-surface);
  --bs-border-color-translucent: var(--tblr-border-color-translucent);
  --bs-border-radius: var(--tblr-border-radius);
  --bs-secondary-color: var(--tblr-secondary-color);
  --bs-highlight-bg: var(--tblr-highlight-bg);
}

.cv-typeahead-select-popup {
  box-shadow: var(--tblr-shadow-dropdown);
}

/* Tabler's .dropdown-item is a flex row with a gap, which splits a match highlight (<mark>) off the rest of the word */
.cv-typeahead .dropdown-item,
.cv-typeahead-select .dropdown-item {
  display: block;
}

/* A bare <table class="table"> straight in the page content (crud_views_workflow's history table has no
   .table-responsive wrapper and no class to hook) is wider than a phone. The content container scrolls sideways
   instead of the page; the table itself stays a table, so a narrow one still spans the full width. */
@media (max-width: 767.98px) {
  .page-body > .container-xl:has(> table.table) {
    overflow-x: auto;
  }
}
